INSERT INTO blog_posts (title, slug, content, excerpt, author, is_published, featured_image, tags, meta_title, meta_description, published_at) VALUES
('Understanding GNSS Technology in Modern Surveying', 'understanding-gnss-technology-modern-surveying-applications', '<h2>The Evolution of GNSS Technology</h2><p>Global Navigation Satellite System (GNSS) technology has revolutionized the surveying industry, providing unprecedented accuracy and efficiency in positioning applications...</p>', 'Comprehensive guide to GNSS technology and its applications in modern surveying practices.', 'CV. Aprinia Geosat Technical Team', true, 'https://images.unsplash.com/photo-1581094794329-c8112a89af12?w=800', '["gnss", "surveying", "technology", "gps"]', 'Understanding GNSS Technology in Modern Surveying Applications', 'Comprehensive guide to GNSS technology, applications, and benefits in modern surveying and mapping practices.', NOW() - INTERVAL '7 days'),

('Total Station vs GNSS: Choosing the Right Equipment', 'total-station-vs-gnss-choosing-right-surveying-equipment', '<h2>Comparing Survey Technologies</h2><p>When planning a surveying project, one of the most important decisions is choosing between total station and GNSS technology...</p>', 'Expert comparison guide for selecting between total station and GNSS equipment for different surveying projects.', 'CV. Aprinia Geosat Technical Team', true, 'https://images.unsplash.com/photo-1581094289206-c0ddd9e21b0e?w=800', '["total-station", "gnss", "comparison", "equipment"]', 'Total Station vs GNSS: Choosing the Right Surveying Equipment', 'Expert comparison guide for selecting between total station and GNSS equipment for optimal surveying results.', NOW() - INTERVAL '14 days'),

('Best Practices for RTK GNSS Surveying', 'best-practices-rtk-gnss-surveying-accuracy-tips', '<h2>Maximizing RTK GNSS Accuracy</h2><p>Real-Time Kinematic (RTK) GNSS surveying offers centimeter-level accuracy, but achieving optimal results requires following established best practices...</p>', 'Professional tips and best practices for achieving maximum accuracy with RTK GNSS surveying systems.', 'CV. Aprinia Geosat Technical Team', true, 'https://images.unsplash.com/photo-1581094794329-c8112a89af12?w=800', '["rtk", "gnss", "best-practices", "accuracy"]', 'Best Practices for RTK GNSS Surveying - Accuracy Tips', 'Professional tips and best practices for achieving maximum accuracy with RTK GNSS surveying systems and equipment.', NOW() - INTERVAL '21 days');
